-- Reputly production schema. Apply through Supabase migrations.
-- No customer narrative, model input/output, card details, or raw webhook payloads.
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',locale text not null default 'en',created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 2 and 160),country_code char(2) not null,default_locale text not null default 'en',status text not null default 'active' check(status in('active','suspended','deleting')),terms_accepted_at timestamptz not null,created_at timestamptz not null default now(),deletion_requested_at timestamptz,deletion_due_at timestamptz);
create table public.organization_members(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('organization_admin','location_manager')),accepted_at timestamptz,created_at timestamptz not null default now(),primary key(organization_id,user_id));
create index members_user_idx on public.organization_members(user_id);
create table public.locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null check(length(name) between 2 and 160),category text not null,country_code char(2) not null,locale text not null default 'en',timezone text not null default 'Asia/Kolkata',address text not null default '',brand_color text not null default '#315b43' check(brand_color ~ '^#[A-Fa-f0-9]{6}$'),google_review_url text,status text not null default 'draft' check(status in('draft','active','archived')),destination_confirmed_at timestamptz,created_at timestamptz not null default now(),archived_at timestamptz,unique(id,organization_id),check(status<>'active' or (google_review_url is not null and destination_confirmed_at is not null)),check(google_review_url is null or google_review_url ~ '^https://(search|www)\.google\.com/local/writereview\?placeid=ChI[A-Za-z0-9_-]+$'));
create index locations_org_idx on public.locations(organization_id);
create table public.location_assignments(organization_id uuid not null,location_id uuid not null,user_id uuid not null,primary key(location_id,user_id),foreign key(location_id,organization_id) references public.locations(id,organization_id) on delete cascade,foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id) on delete cascade);
create table public.qr_codes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,location_id uuid not null,slug text not null unique check(slug ~ '^[A-Za-z0-9_-]{24,64}$'),label text not null default 'Share your experience' check(length(label) between 2 and 70),brand_color text not null default '#315b43' check(brand_color ~ '^#[A-Fa-f0-9]{6}$'),is_active boolean not null default true,created_at timestamptz not null default now(),foreign key(location_id,organization_id) references public.locations(id,organization_id) on delete cascade,unique(id,organization_id,location_id));
create index qr_org_location_idx on public.qr_codes(organization_id,location_id);
create table public.public_sessions(id uuid primary key default gen_random_uuid(),qr_code_id uuid not null references public.qr_codes(id) on delete cascade,token_hash text not null unique,started_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '24 hours',ai_attempts integer not null default 0 check(ai_attempts>=0));
create table public.analytics_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,location_id uuid not null,qr_code_id uuid not null,session_id uuid references public.public_sessions(id) on delete set null,event_type text not null check(event_type in('qr_opened','assist_started','ai_draft_completed','copy_clicked','review_link_clicked')),occurred_at timestamptz not null default now(),dedupe_key text not null unique,foreign key(qr_code_id,organization_id,location_id) references public.qr_codes(id,organization_id,location_id) on delete cascade);
create index events_org_date_idx on public.analytics_events(organization_id,occurred_at);
create table public.analytics_daily(organization_id uuid not null,location_id uuid not null,qr_code_id uuid not null,day date not null,event_type text not null,event_count bigint not null default 0,primary key(qr_code_id,day,event_type),foreign key(qr_code_id,organization_id,location_id) references public.qr_codes(id,organization_id,location_id) on delete cascade);
create index daily_org_day_idx on public.analytics_daily(organization_id,day);
create table public.plans(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,currency char(3) not null,amount_minor integer not null check(amount_minor>0),billing_period text not null default 'month' check(billing_period='month'),location_limit integer not null check(location_limit>0),ai_monthly_limit integer not null check(ai_monthly_limit>=0),is_active boolean not null default true);
insert into public.plans(code,name,currency,amount_minor,location_limit,ai_monthly_limit) values('starter-inr','Starter','INR',39900,1,500),('growth-inr','Growth','INR',99900,3,3000),('business-inr','Business','INR',299900,10,10000),('starter-usd','Starter','USD',900,1,500),('growth-usd','Growth','USD',2400,3,3000),('business-usd','Business','USD',7900,10,10000);
create table public.subscriptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id) on delete cascade,plan_id uuid not null references public.plans(id),provider text not null default 'cashfree',provider_subscription_id text unique,status text not null default 'trialing' check(status in('trialing','pending','active','past_due','cancelled','expired')),trial_ends_at timestamptz,current_period_start timestamptz,current_period_end timestamptz,grace_until timestamptz,cancel_requested_at timestamptz,last_reconciled_at timestamptz,created_at timestamptz not null default now());
create table public.usage_counters(organization_id uuid not null references public.organizations(id) on delete cascade,period_start date not null,ai_requests integer not null default 0 check(ai_requests>=0),primary key(organization_id,period_start));
create table public.ai_usage(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,session_id uuid references public.public_sessions(id) on delete set null,model text not null,prompt_version text not null,input_tokens integer not null default 0,output_tokens integer not null default 0,cost_minor_estimate numeric(12,4),currency char(3) not null default 'USD',status text not null check(status in('reserved','completed','failed','fallback')),created_at timestamptz not null default now());
create table public.checkout_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_id uuid not null references public.plans(id),idempotency_key text not null,provider_subscription_id text not null unique,subscription_session_id text,status text not null default 'pending' check(status in('pending','ready','active','failed','cancelled')),created_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create table public.billing_events(id uuid primary key default gen_random_uuid(),provider text not null default 'cashfree',provider_event_id text not null unique,event_type text not null,received_at timestamptz not null default now(),processed_at timestamptz,status text not null default 'received' check(status in('received','processed','ignored','failed')));
create table public.payment_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),subscription_id uuid references public.subscriptions(id),provider_payment_id text not null unique,amount_minor integer not null,currency char(3) not null,status text not null check(status in('success','failed','refunded')),paid_at timestamptz,invoice_url text,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid,organization_id uuid references public.organizations(id) on delete set null,action text not null,entity_type text not null,entity_id text,metadata_safe_json jsonb not null default '{}',created_at timestamptz not null default now());
create index audit_org_date_idx on public.audit_logs(organization_id,created_at desc);
create table public.member_invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,email text not null,role text not null default 'location_manager' check(role='location_manager'),token_hash text not null unique,location_ids uuid[] not null,expires_at timestamptz not null default now()+interval '7 days',accepted_at timestamptz,created_at timestamptz not null default now());
create unique index pending_invite_idx on public.member_invitations(organization_id,lower(email)) where accepted_at is null;
create table public.idempotency_records(organization_id uuid references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,operation text not null,key text not null,result_id uuid not null,created_at timestamptz not null default now(),primary key(user_id,operation,key));
create table public.rate_limits(key_hash text not null,window_start timestamptz not null,count integer not null default 1,primary key(key_hash,window_start));

-- Security-definer helpers avoid recursively reading membership policies.
create function public.is_org_admin(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m join public.organizations o on o.id=m.organization_id where m.organization_id=p_org and m.user_id=(select auth.uid()) and m.accepted_at is not null and m.role='organization_admin' and o.status='active'); $$;
create function public.is_org_member(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m join public.organizations o on o.id=m.organization_id where m.organization_id=p_org and m.user_id=(select auth.uid()) and m.accepted_at is not null and o.status='active'); $$;
create function public.can_access_location(p_org uuid,p_loc uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.is_org_admin(p_org) or (public.is_org_member(p_org) and exists(select 1 from public.location_assignments a where a.organization_id=p_org and a.location_id=p_loc and a.user_id=(select auth.uid()))); $$;
create function public.assert_org_admin(p_org uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_org_member(p_org) then raise exception 'TENANT_ACCESS_DENIED';end if;if not public.is_org_admin(p_org) then raise exception 'ROLE_REQUIRED';end if;end; $$;

-- Everything defaults to no access. Public pages use a scoped service query.
do $$ declare t text;begin foreach t in array array['profiles','organizations','organization_members','locations','location_assignments','qr_codes','public_sessions','analytics_events','analytics_daily','plans','subscriptions','usage_counters','ai_usage','checkout_requests','billing_events','payment_records','audit_logs','member_invitations','idempotency_records','rate_limits'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end; $$;
grant select on public.organizations,public.organization_members,public.locations,public.location_assignments,public.qr_codes,public.analytics_daily,public.subscriptions,public.usage_counters,public.ai_usage,public.payment_records,public.audit_logs,public.member_invitations to authenticated;
grant select on public.plans to authenticated,anon;
grant select,insert,update on public.profiles to authenticated;
create policy profile_self on public.profiles for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy org_read on public.organizations for select to authenticated using(public.is_org_member(id));
create policy members_read on public.organization_members for select to authenticated using(public.is_org_admin(organization_id) or(user_id=(select auth.uid()) and public.is_org_member(organization_id)));
create policy location_read on public.locations for select to authenticated using(public.can_access_location(organization_id,id));
create policy assignments_read on public.location_assignments for select to authenticated using(public.can_access_location(organization_id,location_id));
create policy qr_read on public.qr_codes for select to authenticated using(public.can_access_location(organization_id,location_id));
create policy daily_read on public.analytics_daily for select to authenticated using(public.can_access_location(organization_id,location_id));
create policy plan_read on public.plans for select to anon,authenticated using(is_active);
create policy subscription_read on public.subscriptions for select to authenticated using(public.is_org_admin(organization_id));
create policy usage_read on public.usage_counters for select to authenticated using(public.is_org_admin(organization_id));
create policy ai_usage_read on public.ai_usage for select to authenticated using(public.is_org_admin(organization_id));
create policy payments_read on public.payment_records for select to authenticated using(public.is_org_admin(organization_id));
create policy audit_read on public.audit_logs for select to authenticated using(public.is_org_admin(organization_id));
create policy invitations_read on public.member_invitations for select to authenticated using(public.is_org_admin(organization_id));

create function public.create_organization(p_name text,p_country text,p_locale text,p_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid;begin
 if auth.uid() is null then raise exception 'ROLE_REQUIRED';end if;
 if not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'ROLE_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key,0));
 select result_id into result from public.idempotency_records where user_id=auth.uid() and operation='create_org' and key=p_key;if result is not null then return result;end if;
 insert into public.organizations(name,country_code,default_locale,terms_accepted_at) values(p_name,p_country,p_locale,now()) returning id into result;
 insert into public.organization_members(organization_id,user_id,role,accepted_at) values(result,auth.uid(),'organization_admin',now());
 insert into public.subscriptions(organization_id,plan_id,status,trial_ends_at) select result,id,'trialing',now()+interval '14 days' from public.plans where code=case when p_country='IN' then 'growth-inr' else 'growth-usd' end;
 insert into public.idempotency_records(organization_id,user_id,operation,key,result_id) values(result,auth.uid(),'create_org',p_key,result);
 insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),result,'organization_created','organization',result::text);return result;end; $$;

create function public.upsert_location(p_org uuid,p_id uuid,p_values jsonb,p_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid;sub public.subscriptions;lim integer;old public.locations;begin
 if p_id is null then perform public.assert_org_admin(p_org);else if not public.can_access_location(p_org,p_id) then raise exception 'TENANT_ACCESS_DENIED';end if;end if;
 if p_values->>'status'='archived' and not public.is_org_admin(p_org) then raise exception 'ROLE_REQUIRED';end if;
 perform 1 from public.organizations where id=p_org for update;
 if p_id is null then select result_id into result from public.idempotency_records where user_id=auth.uid() and operation='create_location:'||p_org::text and key=p_key;if result is not null then return result;end if;end if;
 select * into sub from public.subscriptions where organization_id=p_org;
 select location_limit into lim from public.plans where id=sub.plan_id;
 if not ((sub.status='trialing' and sub.trial_ends_at>now()) or(sub.current_period_end>now() and sub.status in('active','cancelled')) or(sub.status='past_due' and sub.grace_until>now())) then lim:=0;end if;
 if p_id is not null then select * into old from public.locations where id=p_id and organization_id=p_org;if not found then raise exception 'TENANT_ACCESS_DENIED';end if;end if;
 if coalesce(p_values->>'status',old.status,'draft')<>'archived' and (p_id is null or old.status='archived') and (select count(*) from public.locations where organization_id=p_org and status<>'archived')>=coalesce(lim,0) then raise exception 'LOCATION_LIMIT';end if;
 if p_id is null then
 insert into public.locations(organization_id,name,category,country_code,locale,timezone,address,brand_color,google_review_url,status,destination_confirmed_at) values(p_org,p_values->>'name',p_values->>'category',p_values->>'country_code',p_values->>'locale',p_values->>'timezone',coalesce(p_values->>'address',''),coalesce(p_values->>'brand_color','#315b43'),nullif(p_values->>'google_review_url',''),coalesce(p_values->>'status','draft'),case when(p_values->>'destination_confirmed')::boolean then now() end) returning id into result;
 insert into public.idempotency_records(organization_id,user_id,operation,key,result_id) values(p_org,auth.uid(),'create_location:'||p_org::text,p_key,result);
 else result:=p_id;
 update public.locations set name=coalesce(p_values->>'name',name),category=coalesce(p_values->>'category',category),country_code=coalesce(p_values->>'country_code',country_code),locale=coalesce(p_values->>'locale',locale),timezone=coalesce(p_values->>'timezone',timezone),address=coalesce(p_values->>'address',address),brand_color=coalesce(p_values->>'brand_color',brand_color),google_review_url=case when p_values?'google_review_url' then nullif(p_values->>'google_review_url','') else google_review_url end,status=coalesce(p_values->>'status',status),destination_confirmed_at=case when p_values?'google_review_url' then case when(p_values->>'destination_confirmed')::boolean then now() end else destination_confirmed_at end,archived_at=case when p_values->>'status'='archived' then now() when p_values->>'status' in('draft','active') then null else archived_at end where id=result;
 end if;
 insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),p_org,case when p_id is null then 'location_created' else 'location_updated' end,'location',result::text);return result;end; $$;

create function public.upsert_qr(p_org uuid,p_id uuid,p_values jsonb,p_key text,p_slug text) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid;loc uuid;begin
 if p_id is null then loc:=(p_values->>'location_id')::uuid;else select location_id into loc from public.qr_codes where id=p_id and organization_id=p_org;end if;
 if not public.can_access_location(p_org,loc) then raise exception 'TENANT_ACCESS_DENIED';end if;
 perform 1 from public.locations where id=loc and organization_id=p_org for update;
 if p_id is null then
 select result_id into result from public.idempotency_records where user_id=auth.uid() and operation='create_qr:'||p_org::text and key=p_key;if result is not null then return result;end if;
 insert into public.qr_codes(organization_id,location_id,slug,label,brand_color) values(p_org,loc,p_slug,p_values->>'label',p_values->>'brand_color') returning id into result;
 insert into public.idempotency_records(organization_id,user_id,operation,key,result_id) values(p_org,auth.uid(),'create_qr:'||p_org::text,p_key,result);
 else result:=p_id;update public.qr_codes set label=coalesce(p_values->>'label',label),brand_color=coalesce(p_values->>'brand_color',brand_color),is_active=coalesce((p_values->>'is_active')::boolean,is_active) where id=result;end if;
 insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),p_org,'qr_updated','qr_code',result::text);return result;end; $$;

create function public.update_organization(p_org uuid,p_name text,p_delete boolean) returns void language plpgsql security definer set search_path='' as $$ begin perform public.assert_org_admin(p_org);update public.organizations set name=coalesce(p_name,name),status=case when p_delete then 'deleting' else status end,deletion_requested_at=case when p_delete then now() else deletion_requested_at end,deletion_due_at=case when p_delete then now()+interval '30 days' else deletion_due_at end where id=p_org;insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),p_org,case when p_delete then 'organization_deletion_requested' else 'organization_updated' end,'organization',p_org::text);end; $$;

create function public.create_invitation(p_org uuid,p_email text,p_hash text,p_locations uuid[]) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid;begin perform public.assert_org_admin(p_org);if cardinality(p_locations)=0 or exists(select 1 from unnest(p_locations) l where not exists(select 1 from public.locations where id=l and organization_id=p_org)) then raise exception 'TENANT_ACCESS_DENIED';end if;delete from public.member_invitations where organization_id=p_org and lower(email)=lower(p_email) and accepted_at is null;insert into public.member_invitations(organization_id,email,token_hash,location_ids) values(p_org,lower(p_email),p_hash,p_locations) returning id into result;insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),p_org,'invitation_created','invitation',result::text);return result;end; $$;
create function public.accept_invitation(p_hash text) returns uuid language plpgsql security definer set search_path='' as $$ declare inv public.member_invitations;mail text;begin select email into mail from auth.users where id=auth.uid() and email_confirmed_at is not null;if mail is null then raise exception 'INVITATION_INVALID';end if;select * into inv from public.member_invitations where token_hash=p_hash and accepted_at is null and expires_at>now() for update;if not found or lower(mail)<>lower(inv.email) or not exists(select 1 from public.organizations where id=inv.organization_id and status='active') then raise exception 'INVITATION_INVALID';end if;if exists(select 1 from public.organization_members where organization_id=inv.organization_id and user_id=auth.uid()) then raise exception 'INVITATION_INVALID';end if;insert into public.organization_members(organization_id,user_id,role,accepted_at) values(inv.organization_id,auth.uid(),'location_manager',now());insert into public.location_assignments(organization_id,location_id,user_id) select inv.organization_id,l,auth.uid() from unnest(inv.location_ids) l where exists(select 1 from public.locations where id=l and organization_id=inv.organization_id);update public.member_invitations set accepted_at=now() where id=inv.id;insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),inv.organization_id,'invitation_accepted','member',auth.uid()::text);return inv.organization_id;end; $$;
create function public.remove_member(p_org uuid,p_user uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform public.assert_org_admin(p_org);if exists(select 1 from public.organization_members where organization_id=p_org and user_id=p_user and role='organization_admin') then raise exception 'ROLE_REQUIRED';end if;delete from public.organization_members where organization_id=p_org and user_id=p_user;insert into public.audit_logs(actor_user_id,organization_id,action,entity_type,entity_id) values(auth.uid(),p_org,'member_removed','member',p_user::text);end; $$;
create function public.team_directory(p_org uuid) returns table(user_id uuid,display_name text,email text,role text,location_ids uuid[]) language sql stable security definer set search_path='' as $$ select m.user_id,coalesce(p.display_name,''),u.email,m.role,array(select a.location_id from public.location_assignments a where a.user_id=m.user_id and a.organization_id=p_org) from public.organization_members m join auth.users u on u.id=m.user_id left join public.profiles p on p.user_id=m.user_id where m.organization_id=p_org and public.is_org_admin(p_org); $$;

-- Public intake and quotas execute with the service role only.
create function public.consume_rate_limit(p_key text,p_seconds integer,p_limit integer) returns boolean language plpgsql security definer set search_path='' as $$ declare bucket timestamptz;n integer;begin bucket:=to_timestamp(floor(extract(epoch from now())/p_seconds)*p_seconds);insert into public.rate_limits(key_hash,window_start,count) values(p_key,bucket,1) on conflict(key_hash,window_start) do update set count=public.rate_limits.count+1 returning count into n;return n<=p_limit;end; $$;
create function public.record_public_event(p_session uuid,p_type text,p_key text) returns void language plpgsql security definer set search_path='' as $$ declare qr public.qr_codes;begin select q.* into qr from public.public_sessions s join public.qr_codes q on q.id=s.qr_code_id join public.locations l on l.id=q.location_id join public.organizations o on o.id=q.organization_id where s.id=p_session and s.expires_at>now() and q.is_active and l.status='active' and o.status='active';if not found then raise exception 'QR_INACTIVE';end if;with added as(insert into public.analytics_events(organization_id,location_id,qr_code_id,session_id,event_type,dedupe_key) values(qr.organization_id,qr.location_id,qr.id,p_session,p_type,p_key) on conflict(dedupe_key) do nothing returning *) insert into public.analytics_daily(organization_id,location_id,qr_code_id,day,event_type,event_count) select organization_id,location_id,qr_code_id,(occurred_at at time zone (select timezone from public.locations where id=qr.location_id))::date,event_type,1 from added on conflict(qr_code_id,day,event_type) do update set event_count=public.analytics_daily.event_count+1;end; $$;
create function public.reserve_ai(p_session uuid,p_model text) returns uuid language plpgsql security definer set search_path='' as $$ declare org uuid;sub public.subscriptions;lim integer;n integer;result uuid;begin
 select q.organization_id into org from public.public_sessions s join public.qr_codes q on q.id=s.qr_code_id join public.locations l on l.id=q.location_id join public.organizations o on o.id=q.organization_id where s.id=p_session and s.expires_at>now() and q.is_active and l.status='active' and o.status='active';if org is null then raise exception 'QR_INACTIVE';end if;
 perform 1 from public.organizations where id=org for update;
 select * into sub from public.subscriptions where organization_id=org;
 if not ((sub.status='trialing' and sub.trial_ends_at>now()) or(sub.status in('active','cancelled') and sub.current_period_end>now()) or(sub.status='past_due' and sub.grace_until>now())) then raise exception 'AI_QUOTA_EXCEEDED';end if;
 select ai_monthly_limit into lim from public.plans where id=sub.plan_id;
 update public.public_sessions set ai_attempts=ai_attempts+1 where id=p_session and expires_at>now() and ai_attempts<3 returning ai_attempts into n;if not found then raise exception 'AI_QUOTA_EXCEEDED';end if;
 insert into public.usage_counters(organization_id,period_start,ai_requests) values(org,date_trunc('month',now() at time zone 'UTC')::date,0) on conflict do nothing;
 update public.usage_counters set ai_requests=ai_requests+1 where organization_id=org and period_start=date_trunc('month',now() at time zone 'UTC')::date and ai_requests<lim;if not found then raise exception 'AI_QUOTA_EXCEEDED';end if;
 insert into public.ai_usage(organization_id,session_id,model,prompt_version,status) values(org,p_session,p_model,'rewrite-v1','reserved') returning id into result;return result;end; $$;
create function public.finish_ai(p_id uuid,p_status text,p_input integer,p_output integer) returns void language plpgsql security definer set search_path='' as $$ declare u public.ai_usage;begin select * into u from public.ai_usage where id=p_id and status='reserved' for update;if not found then return;end if;update public.ai_usage set status=p_status,input_tokens=p_input,output_tokens=p_output where id=p_id;if p_status='failed' then update public.usage_counters set ai_requests=greatest(0,ai_requests-1) where organization_id=u.organization_id and period_start=date_trunc('month',u.created_at at time zone 'UTC')::date;end if;if p_status='completed' then perform public.record_public_event(u.session_id,'ai_draft_completed','draft:'||u.id::text);end if;end; $$;

-- All function grants are explicit. Never expose service mutations to anon/auth.
revoke all on all functions in schema public from public,anon,authenticated;
grant execute on function public.is_org_admin(uuid),public.is_org_member(uuid),public.can_access_location(uuid,uuid),public.create_organization(text,text,text,text),public.upsert_location(uuid,uuid,jsonb,text),public.upsert_qr(uuid,uuid,jsonb,text,text),public.update_organization(uuid,text,boolean),public.create_invitation(uuid,text,text,uuid[]),public.accept_invitation(text),public.remove_member(uuid,uuid),public.team_directory(uuid) to authenticated;
grant execute on all functions in schema public to service_role;
